import {renderView,section,list,button,textarea,field} from '../ui/view.js';import {ManuscriptService} from './literary-services-manuscript-service.js';import {StoryService} from '../services/story-service.js';import {el} from './literary-core-dom.js';import {notify} from './literary-core-notifications.js';
export async function outlineView(){const [nodesR,threadsR]=await Promise.all([ManuscriptService.list(),StoryService.threads()]);const nodes=(nodesR.nodes||[]).filter(n=>['outline','act','chapter','scene','beat'].includes(n.nodeType)),threads=threadsR.threads||threadsR.plotThreads||[];const body=document.createDocumentFragment();const outline=section('Hierarchy',[list(nodes,n=>el('article',{},[el('strong',{text:n.title}),el('p',{text:n.metadata?.summary||''})]),{empty:'No outline items yet.'})]);outline.append(button('Generate outline with project context',async()=>{const prompt=window.prompt('What should the outline focus on?')||'';if(!prompt)return;await StoryService.generateOutline({prompt});notify('Outline generation request completed. Reload to review generated structure.');}));body.append(outline,section('Plot threads',[list(threads,t=>el('article',{},[el('strong',{text:t.name}),el('span',{text:` — ${t.status||'active'}`})]),{empty:'No plot threads yet.'})]));renderView('Outline',{description:'Organize acts, chapters, scenes, beats, summaries, status, and plot-thread participation.',body});}
